using HPD.Agent.Audio;
using HPD.Agent.Audio.Media;
using HPD.Agent.Audio.Policies;
using HPD.Agent.Audio.Runtime.Transports;
using HPD.Agent.Audio.Transports;
using HPD.Agent.Authority;

namespace HPD.Agent.LiveAudio.Contracts.Tests;

public sealed class TransportCoordinatorTests
{
    [Fact] public async Task Finite_content_adapter_migrates_through_S11_lifecycle(){await using var adapter=new ContentInputTransportAdapter(new TransportAdapterId("finite-1"),new AudioSessionId("audio-1"),new InputContentRef{Id=new InputContentId("input-1"),Kind=InputContentKind.Audio,SourceKind=InputContentSourceKind.MetadataOnly,MediaType="audio/wav"},new AudioPolicySet());var state=State(TransportProfile.FiniteContent);var port=new FiniteManualTransportAdapterPort(adapter);state=await A(state,new TransportLifecycleCommand.Bind(OperationId.Create(),0),port);state=await A(state,new TransportLifecycleCommand.Start(OperationId.Create(),1),port);Assert.Equal(TransportAdapterState.Active,adapter.State);state=await A(state,new TransportLifecycleCommand.Stop(OperationId.Create(),2),port);Assert.Equal(TransportLifecycle.Stopped,state.Snapshot.Lifecycle);}
    [Fact] public async Task Manual_adapter_uses_the_same_generation_fenced_coordinator(){var effects=new ScriptedEffectPort();var state=State(TransportProfile.Manual);state=await A(state,new TransportLifecycleCommand.Bind(OperationId.Create(),0),effects);state=await A(state,new TransportLifecycleCommand.Start(OperationId.Create(),1),effects);Assert.Equal(1,effects.Starts);}
    [Fact] public async Task Adapter_unknown_outcome_preserves_lifecycle(){var effects=new ScriptedEffectPort{Unknown=true};var state=State(TransportProfile.Manual);state=await A(state,new TransportLifecycleCommand.Bind(OperationId.Create(),0),effects);var result=Assert.IsType<TransportCoordinatorResult.OutcomeUnknown>(await TransportCoordinator.ApplyAsync(state,new TransportLifecycleCommand.Start(OperationId.Create(),1),effects,8));Assert.Equal(TransportLifecycle.Bound,result.State.Snapshot.Lifecycle);}
    [Fact] public async Task Retry_is_exact_and_changed_reuse_conflicts(){var effects=new ScriptedEffectPort();var state=State(TransportProfile.Manual);var command=new TransportLifecycleCommand.Bind(OperationId.Create(),0);var applied=Assert.IsType<TransportCoordinatorResult.Applied>(await TransportCoordinator.ApplyAsync(state,command,effects,8));Assert.IsType<TransportCoordinatorResult.Duplicate>(await TransportCoordinator.ApplyAsync(applied.State,command,effects,8));Assert.IsType<TransportCoordinatorResult.Rejected>(await TransportCoordinator.ApplyAsync(applied.State,new TransportLifecycleCommand.Start(command.OperationId,1),effects,8));}
    [Fact] public void Transport_generation_must_match_the_S11_axis(){var s=new SessionAuthorityStampV1(RuntimeGenerationId.Create(),LiveSessionId.Create());var g=TransportGenerationId.Create();var a=ExpectedAuthorityVectorV1.Create(s,[new AuthorityAxisValueV1.Transport(TransportGenerationId.Create())]);Assert.Throws<ArgumentException>(()=>new TransportPlan(OperationId.Create(),TransportProfile.Manual,g,a));}
    private static TransportCoordinatorState State(TransportProfile profile){var s=new SessionAuthorityStampV1(RuntimeGenerationId.Create(),LiveSessionId.Create());var g=TransportGenerationId.Create();var a=ExpectedAuthorityVectorV1.Create(s,[new AuthorityAxisValueV1.Transport(g)]);return TransportCoordinator.Create(new(OperationId.Create(),profile,g,a));}
    private static async Task<TransportCoordinatorState> A(TransportCoordinatorState s,TransportLifecycleCommand c,ITransportLifecycleEffectPort p)=>Assert.IsType<TransportCoordinatorResult.Applied>(await TransportCoordinator.ApplyAsync(s,c,p,8)).State;
    private sealed class ScriptedEffectPort:ITransportLifecycleEffectPort{public bool Unknown{get;set;}public int Starts{get;private set;}public ValueTask<TransportAdapterEffectResult> ApplyAsync(TransportLifecycleCommand command,CancellationToken cancellationToken){cancellationToken.ThrowIfCancellationRequested();if(Unknown&&command is TransportLifecycleCommand.Start)return ValueTask.FromResult<TransportAdapterEffectResult>(new TransportAdapterEffectResult.OutcomeUnknown(new BoundedAscii("transport-adapter-outcome-unknown")));if(command is TransportLifecycleCommand.Start)Starts++;return ValueTask.FromResult<TransportAdapterEffectResult>(new TransportAdapterEffectResult.Completed());}}
}
